import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

type VendorOut = { id: string; status: string };
type DocumentOut = { id: string; kind: string; status: string };
type ExtractionOut = { id: string; status: string };
type AuditTrail = { items: { action: string }[] };

const DOCUMENT_KINDS = ["w9", "insurance_certificate", "contract"] as const;

function uniqueSlug(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function uploadDocument(member: APIRequestContext, vendorId: string, kind: string): Promise<DocumentOut> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${kind}.pdf`,
        mimeType: "application/pdf",
        buffer: Buffer.from(`%PDF-1.4 ${kind} ${uniqueSlug("doc")}`),
      },
    },
  });
  return expectStatus<DocumentOut>(response, 201);
}

test.describe("review vendors", () => {
  test(
    "approving every extraction approves the vendor",
    { tag: "@REV-05" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads all three documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const created = await expectStatus<VendorOut>(
        await member.post("/api/vendors", {
          data: {
            name: `Approval Vendor ${uniqueSlug("v")}`,
            category: "services",
            contact_email: `${uniqueSlug("contact")}@example.com`,
          },
        }),
        201,
      );

      const documents: DocumentOut[] = [];
      for (const kind of DOCUMENT_KINDS) {
        documents.push(await uploadDocument(member, created.id, kind));
      }

      // Wait for extraction to finish on every document.
      for (const document of documents) {
        await expect
          .poll(
            async () =>
              (await expectStatus<DocumentOut>(await member.get(`/api/documents/${document.id}`), 200)).status,
            { timeout: 60_000 },
          )
          .toBe("extracted");
      }

      // Collect the three pending extractions.
      const extractions: ExtractionOut[] = [];
      for (const document of documents) {
        const extraction = await expectStatus<ExtractionOut>(
          await member.get(`/api/documents/${document.id}/extraction`),
          200,
        );
        expect(extraction.status).toBe("pending_review");
        extractions.push(extraction);
      }

      // The member submits the vendor for review.
      const submitted = await expectStatus<VendorOut>(
        await member.post(`/api/vendors/${created.id}/submit`),
        200,
      );
      expect(submitted.status).toBe("in_review");

      // Act: the reviewer approves all three extractions.
      for (const extraction of extractions) {
        const decided = await expectStatus<ExtractionOut>(
          await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
            data: { decision: "approve" },
          }),
          200,
        );
        expect(decided.status).toBe("approved");
      }

      // Assert: the vendor is approved.
      const vendor = await expectStatus<VendorOut>(await member.get(`/api/vendors/${created.id}`), 200);
      expect(vendor.status).toBe("approved");

      // Assert: an audit event for the approval is recorded.
      const audit = await expectStatus<AuditTrail>(await member.get(`/api/vendors/${created.id}/audit`), 200);
      const actions = audit.items.map((event) => event.action);
      expect(actions).toContain("vendor.approved");
    },
  );
});
